public class DeduplicationTransformer implements ValueTransformerWithKey<String, Event, Event> {
    private KeyValueStore<String, Long> dedupStore;
    @Override
    public Event transform(String key, Event value) {
        if (dedupStore.get(key) != null) return null; // Drop duplicate
        dedupStore.put(key, System.currentTimeMillis());
        return value;
    }
}

